3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * When a create request sets {@code sharesHousehold} true and an existing owner already shares this
14	 * owner's last name and address, both are given the same {@code householdId} so the shared household
15	 * is discoverable. The id is a stable identifier derived from the normalized last name and address
16	 * (upper-case hex prefix of their SHA-256), so every member of a household computes the same value.
17	 *
18	 * <p>Last name and address are compared case-insensitively with collapsed whitespace, matching
19	 * {@link EnsureUniqueHousehold}. Runs after {@link BuildOwner} within the create transaction: it sets
20	 * the id on the new owner (persisted by {@link SaveOwner}) and saves any existing members that did not
21	 * yet carry it. A request without {@code sharesHousehold}, or one with no matching owner, is left
22	 * untouched.
23	 */
24	public class AssignHousehold {
25	
26	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
27	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return;
29	        }
30	        String lastName = normalize(owner.getLastName());
31	        String address = normalize(owner.getAddress());
32	        java.util.List<Owner> household = new java.util.ArrayList<>();
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (normalize(existing.getLastName()).equals(lastName)
35	                    && normalize(existing.getAddress()).equals(address)) {
36	                household.add(existing);
37	            }
38	        }
39	        if (household.isEmpty()) {
40	            return;
41	        }
42	        String householdId = householdId(lastName, address);
43	        owner.setHouseholdId(householdId);
44	        for (Owner member : household) {
45	            if (!householdId.equals(member.getHouseholdId())) {
46	                member.setHouseholdId(householdId);
47	                ownerRepository.save(member);
48	            }
49	        }
50	    }
51	
52	    private static String householdId(String lastName, String address) {
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder(16);
57	            for (int i = 0; i < 8; i++) {
58	                sb.append(String.format("%02x", digest[i]));
59	            }
60	            return sb.toString().toUpperCase();
61	        }
62	        catch (NoSuchAlgorithmException e) {
63	            throw new IllegalStateException("SHA-256 unavailable", e);
64	        }
65	    }
66	
67	    private static String normalize(String value) {
68	        if (value == null) {
69	            return "";
70	        }
71	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
72	    }
73	}
