11	 * cannot share a household by accident. Last name and address are compared case-insensitively with
12	 * collapsed whitespace (leading/trailing trimmed, internal runs reduced to a single space). Runs
13	 * before {@link BuildOwner}; a match is a 409 via {@link DuplicateHouseholdException}. A request that
14	 * explicitly sets {@code sharesHousehold} true opts out of this check and is allowed.
15	 */
16	public class EnsureUniqueHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String lastName = normalize(request.getLastName());
24	        String address = normalize(request.getAddress());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (normalize(existing.getLastName()).equals(lastName)
27	                    && normalize(existing.getAddress()).equals(address)) {
28	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
29	            }
30	        }
31	    }
32	
33	    private static String normalize(String value) {
34	        if (value == null) {
35	            return "";
36	        }
37	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
